using System;
using System.Collections;
using System.Collections.Generic;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

public class PlayerDiceHandPositioningAnimationManager : ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>
{
	[Header("Dice In Hand Position")]
	[SerializeField]
	private float diceDistanceHorizontal = 1.25f;

	[SerializeField]
	private float diceDistanceVertical = 0.1f;

	[SerializeField]
	private Vector2 diceStartPositionEven = new Vector2(0.5f, -4f);

	[SerializeField]
	private Vector2 diceStartPositionOdds = new Vector2(0f, -4f);

	[Header("IOS Landscape: Dice In Hand Position")]
	[SerializeField]
	private float diceDistanceVerticalIOSLandscape = 0.08f;

	[SerializeField]
	private Vector2 diceStartPositionEvenIOSLandscape = new Vector2(0.59f, -3.65f);

	[SerializeField]
	private Vector2 diceStartPositionOddsIOSLandscape = new Vector2(0f, -3.71f);

	[Header("Dice In Hand Rotation")]
	[SerializeField]
	private float diceXRotation;

	[SerializeField]
	private float diceZRotationMultiplier = 1f;

	[Header("Hand Limit")]
	[SerializeField]
	private int handLimit = 8;

	[SerializeField]
	private float discardDicePassingHandLimitDelay;

	[Header("References")]
	[SerializeField]
	private ListDiceInstanceEvent OnDiscardUsedDicesWithoutExhaust;

	private List<DiceInstance> diceInHandAux = new List<DiceInstance>();

	private List<DiceInstance> diceToBeDiscardedFromHandLimit = new List<DiceInstance>();

	private Vector3[] diceFaceRotation;

	public int HandLimit => handLimit;

	public Vector3[] DiceFaceRotation => diceFaceRotation;

	protected override void Awake()
	{
		base.Awake();
		diceFaceRotation = new Vector3[6]
		{
			new Vector3(0f, 0f, 0f),
			new Vector3(180f, 0f, 180f),
			new Vector3(90f, 180f, 0f),
			new Vector3(90f, 0f, 0f),
			new Vector3(0f, 270f, 0f),
			new Vector3(0f, 90f, 0f)
		};
	}

	private void CategorizeDiceInPlay(List<DiceInstance> allPlayerDicesInPlay)
	{
		diceInHandAux.Clear();
		int num = 0;
		for (int i = 0; i < allPlayerDicesInPlay.Count; i++)
		{
			DiceInstance diceInstance = allPlayerDicesInPlay[i];
			DiceState diceState = diceInstance.DiceState;
			if (diceState != DiceState.Rolling && !(diceInstance.Dice as PlayerDice).DiceJustPlayed)
			{
				num++;
			}
			if (num > handLimit)
			{
				diceToBeDiscardedFromHandLimit.Add(diceInstance);
			}
			else if (diceState == DiceState.OnHand || diceState == DiceState.ReturningToHandAfterDrag || diceState == DiceState.FinishedRolling || diceState == DiceState.ReturningToHandAfterDiceCastSpace || diceState == DiceState.ReturningToHandAfterTargetSpace)
			{
				diceInHandAux.Add(diceInstance);
			}
		}
	}

	public void UpdateDiceInHandPosition(Action afterPositionedAction = null)
	{
		Debug.Log("Updating dice in hand position");
		List<DiceInstance> handDices = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;
		CategorizeDiceInPlay(handDices);
		int num = Mathf.FloorToInt((float)diceInHandAux.Count / 2f);
		bool flag = diceInHandAux.Count % 2 == 0;
		int num2 = -num;
		float num3 = -num;
		Vector2 vector = (flag ? diceStartPositionEven : diceStartPositionOdds);
		for (int i = 0; i < diceInHandAux.Count; i++)
		{
			DiceInstance diceInstance = diceInHandAux[i];
			float num4 = diceDistanceVertical;
			Vector2 vector2 = new Vector2(vector.x + diceDistanceHorizontal * (float)num2, vector.y + num3 * num4);
			DiceState diceState = diceInstance.DiceState;
			float rotationZ = ((!flag) ? ((float)(num - i) * diceZRotationMultiplier) : ((i == num - 1 || i == num) ? 0f : ((i >= num) ? ((float)(num - i) * diceZRotationMultiplier) : ((float)(num - i - 1) * diceZRotationMultiplier))));
			switch (diceState)
			{
			case DiceState.FinishedRolling:
				diceInstance.PlayAnimationAfterDiceDraw(vector2, diceXRotation, rotationZ, afterPositionedAction);
				break;
			case DiceState.ReturningToHandAfterDrag:
			case DiceState.ReturningToHandAfterDiceCastSpace:
				diceInstance.PlayGoBackToHandFromDiceCastSpaceOrFromDragAnimation(vector2, diceXRotation, rotationZ);
				break;
			case DiceState.ReturningToHandAfterTargetSpace:
				diceInstance.PlayGoBackToHandFromTargetSpaceAnimation(vector2, diceXRotation, rotationZ);
				break;
			case DiceState.OnHand:
				diceInstance.DiceMovement.PlayAdjustDicePositionInHand(vector2, diceXRotation, rotationZ);
				break;
			}
			num2++;
			if (i >= num && !flag)
			{
				num3 -= 1f;
			}
			else if (!(i == num - 1 && flag))
			{
				num3 = ((i < num) ? (num3 + 1f) : (num3 - 1f));
			}
		}
		CheckHandLimitAfterDraw(afterPositionedAction);
	}

	private void CheckHandLimitAfterDraw(Action afterPositionedAction)
	{
		if (diceToBeDiscardedFromHandLimit.Count != 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DisposeHandLimitDices(afterPositionedAction));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
	}

	private IEnumerator DisposeHandLimitDices(Action afterPositionedAction)
	{
		List<DiceInstance> tempDiceToBeDiscardedFromHandLimit = diceToBeDiscardedFromHandLimit.Duplicate();
		diceToBeDiscardedFromHandLimit.Clear();
		PlayerEffects playerEffects = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		bool isPlayerBoostActive = playerEffects.IsPlayerBoostActive(activateFeedback: false);
		bool isPlayerLinkBoostActive = playerEffects.IsPlayerLinkBoostActive(activateFeedback: false);
		yield return new WaitForSeconds(discardDicePassingHandLimitDelay);
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn && (isPlayerBoostActive || isPlayerLinkBoostActive))
		{
			yield return new WaitForSeconds(0.4f);
			playerEffects.IsPlayerBoostActive(activateFeedback: true);
			playerEffects.IsPlayerLinkBoostActive(activateFeedback: true);
			yield return new WaitForSeconds(0.5f);
			if (isPlayerBoostActive)
			{
				playerEffects.ActivatePlayerBoostPurification(tempDiceToBeDiscardedFromHandLimit.Count, !ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData);
			}
			if (isPlayerLinkBoostActive)
			{
				playerEffects.ActivatePlayerBoostPurification(tempDiceToBeDiscardedFromHandLimit.Count, removeBoost: false);
			}
			yield return new WaitForSeconds(0.4f);
			if (!ReferenceSingleton<DiceRollingHandler>.Instance.IsDiceRolling)
			{
				playerEffects.IsPlayerBoostActiveRemoveIt();
				ReferenceSingleton<PlayerDiceHandHolder>.Instance.SetDefaultDrawDicesAmount();
				ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDrawDiceAmountWithOmensModifiers();
			}
		}
		for (int i = 0; i < tempDiceToBeDiscardedFromHandLimit.Count; i++)
		{
			tempDiceToBeDiscardedFromHandLimit[i].AfterDiscardAction = delegate
			{
				afterPositionedAction?.Invoke();
			};
		}
		OnDiscardUsedDicesWithoutExhaust.Raise(tempDiceToBeDiscardedFromHandLimit.Duplicate());
	}

	public void CheckIfAnyDiceIsBeingDraggedAndCancelDrag()
	{
		List<DiceInstance> handDices = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;
		for (int i = 0; i < handDices.Count; i++)
		{
			if (handDices[i].Dragging)
			{
				handDices[i].SetDiceState(DiceState.ReturningToHandAfterTargetSpace);
				handDices[i].SetDragging(value: false);
				ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
				break;
			}
		}
	}

	public void CheckShortcutInputDiceStartFollowingMouse()
	{
		List<DiceInstance> list = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Duplicate();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsFollowingMouse())
			{
				return;
			}
		}
		list.RemoveAll((DiceInstance diceInstance) => diceInstance.DiceState != DiceState.OnHand);
		for (int j = 0; j < list.Count; j++)
		{
			if (ReferenceSingleton<InputManager>.Instance.GetDiceButtonUpInputs[j]())
			{
				list[j].StartFollowingMouse();
			}
		}
	}
}
